/*Select ISNULL(SUM(AP_PaymentHeader.Amount), 0) AS Amount From AP_PaymentHeader Inner Join ( SELECT Distinct AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.PaymentID From AR_InvoiceHeader INNER JOIN AR_InvoiceDetail ON AR_InvoiceDetail.CompanyID = AR_InvoiceHeader.CompanyID AND AR_InvoiceDetail.PeriodID = AR_InvoiceHeader.PeriodID AND AR_InvoiceDetail.InvoiceHeaderID = AR_InvoiceHeader.InvoiceID AND AR_InvoiceDetail.Status = 1 INNER JOIN Inv_StockTransactionDetail On Inv_StockTransactionDetail.CompanyID = AR_InvoiceDetail.CompanyID AND Inv_StockTransactionDetail.PeriodID = AR_InvoiceDetail.PeriodID AND Inv_StockTransactionDetail.TransactionDetailID = AR_InvoiceDetail.StockDetailID AND Inv_StockTransactionDetail.StockTransactionID = AR_InvoiceDetail.StockHeaderID INNER JOIN AP_PurchaseOrderDetail On AP_PurchaseOrderDetail.CompanyID = Inv_StockTransactionDetail.CompanyID AND AP_PurchaseOrderDetail.PeriodID = Inv_StockTransactionDetail.PeriodID AND AP_PurchaseOrderDetail.PODetailID = Inv_StockTransactionDetail.SourceLineID AND AP_PurchaseOrderDetail.POHeaderID = Inv_StockTransactionDetail.SourceHeaderID INNER JOIN AP_PurchaseOrderHeader On AP_PurchaseOrderHeader.CompanyID = AP_PurchaseOrderDetail.CompanyID AND AP_PurchaseOrderHeader.PeriodID = AP_PurchaseOrderDetail.PeriodID AND AP_PurchaseOrderHeader.POHeaderID = AP_PurchaseOrderDetail.POHeaderID AND AP_PurchaseOrderHeader.TypeCode = Inv_StockTransactionDetail.SourceDocumentTypeID AND AP_PurchaseOrderHeader.DocumentNumber = Inv_StockTransactionDetail.SourceCode INNER JOIN AP_PaymentHeader ON AP_PaymentHeader.CompanyID = AP_PurchaseOrderHeader.CompanyID AND AP_PaymentHeader.PeriodID = AP_PurchaseOrderHeader.PeriodID AND AP_PaymentHeader.POHeaderID = AP_PurchaseOrderHeader.POHeaderID AND AP_PaymentHeader.Status = 1 INNER JOIN SET_DocumentType ON SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND SET_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND SET_DocumentType.Status = 1 AND SET_DocumentType.DocumentType LIKE @DocumentTypeName + '%' AND (SET_DocumentType.GroupID = @DocumentGroupID OR @DocumentGroupID IS NULL) WHERE AR_InvoiceHeader.CompanyID = @CompanyID AND AR_InvoiceHeader.PeriodID = @PeriodID AND AR_InvoiceHeader.Status = 1 AND AR_InvoiceHeader.InvoiceID = @DocumentNo ) As PaymentHeader On PaymentHeader.CompanyID = AP_PaymentHeader.CompanyID And PaymentHeader.PeriodID = AP_PaymentHeader.PeriodID And PaymentHeader.PaymentID = AP_PaymentHeader.PaymentID */
Select Sum(Fintab.Amount) From ( SELECT ISNULL(SUM(InnerTab.Amount), 0) AS Amount FROM ( SELECT Distinct GL_TransactionDetail.Amount, GL_TransactionHeader.TransactionID FROM GL_TransactionHeader INNER JOIN GL_TransactionDetail ON GL_TransactionHeader.TransactionID = GL_TransactionDetail.TransactionID AND GL_TransactionHeader.PeriodID = GL_TransactionDetail.PeriodID AND GL_TransactionHeader.CompanyID = GL_TransactionDetail.CompanyID Inner Join Set_DocumentType On Set_DocumentType.DocumentTypeID = GL_TransactionHeader.DocumentTypeID AND Set_DocumentType.PeriodID = GL_TransactionHeader.PeriodID AND Set_DocumentType.CompanyID = GL_TransactionHeader.CompanyID WHERE GL_TransactionHeader.CompanyID = @CompanyID AND GL_TransactionHeader.PeriodID = @PeriodID AND GL_TransactionHeader.DocumentNo = (SELECT InvoiceNumber FROM AR_InvoiceHeader WHERE CompanyID = @CompanyID AND PeriodID = @PeriodID And InvoiceID = @DocumentNo) AND GL_TransactionHeader.DocumentTypeID = (SELECT InvoiceType FROM AR_InvoiceHeader WHERE CompanyID = @CompanyID AND PeriodID = @PeriodID And InvoiceID = @DocumentNo) AND GL_TransactionDetail.CodeCombinationID in ( SELECT Distinct DefaultAccountCode FROM SET_DocumentType WHERE DocumentType like 'Advance Against PO%' AND CompanyID = @CompanyID AND PeriodID = @PeriodID ) AND GL_TransactionHeader.FiscalID = (SELECT FiscalID FROM AR_InvoiceHeader WHERE CompanyID = @CompanyID AND PeriodID = @PeriodID And InvoiceID = @DocumentNo) AND GL_TransactionDetail.TransactionType = 'Credit' And (Set_DocumentType.DocumentType like 'Advance Against PO%' Or Set_DocumentType.DocumentType like 'Vendor Invoice%') ) As InnerTab
Union All -- Work Order scenario -> Work Order - Advance against Work Order - Direct Invoice against Receipt Select IsNull(AP_PaymentHeader.Amount, 0) - PreviousInvoices.Amount As Amount From AR_InvoiceHeader Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_InvoiceHeader.CompanyID And Set_DocumentType.PeriodID = AR_InvoiceHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_InvoiceHeader.InvoiceType And Set_DocumentType.DocumentType Like 'DI-Invoice%' Inner Join AP_PaymentHeader On AP_PaymentHeader.CompanyID = AR_InvoiceHeader.CompanyID And AP_PaymentHeader.PeriodID = AR_InvoiceHeader.PeriodID And AP_PaymentHeader.PaymentID = AR_InvoiceHeader.PaymentStatusType Inner Join Set_DocumentType As PaymentDocument On PaymentDocument.CompanyID = AP_PaymentHeader.CompanyID And PaymentDocument.PeriodID = AP_PaymentHeader.PeriodID And PaymentDocument.DocumentTypeID = AP_PaymentHeader.DocumentTypeID And PaymentDocument.DocumentType Like 'Advance Against PO%' Outer Apply ( --Previous Invoices against 'Advance against Work Order' Select IsNull(Sum(AmountPaid), 0) As Amount From AR_InvoiceHeader Where CompanyID = AP_PaymentHeader.CompanyID And PeriodID = AP_PaymentHeader.PeriodID And PaymentStatusType = AP_PaymentHeader.PaymentID And InvoiceID <> @DocumentNo ) As PreviousInvoices Where AR_InvoiceHeader.CompanyID = @CompanyID And AR_InvoiceHeader.PeriodID = @PeriodID And AR_InvoiceHeader.InvoiceID = @DocumentNo ) As FinTab

Select FinTab.* From ( select Distinct AP_PaymentHeader.PaymentID, AP_PaymentHeader.DocumentNo, SET_DocumentType.DocumentType, AP_PaymentHeader.DocumentDate from AP_PaymentHeader Inner Join Set_DocumentType ON Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.Status = 1 inner join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID Inner Join UsersInDocumentType On UsersInDocumentType.CompanyID = Set_DocumentType.CompanyID And UsersInDocumentType.DocumentTypeID = Set_DocumentType.DocumentTypeID where AP_PaymentHeader.Status = 1 And AP_PaymentHeader.CompanyID = @CompanyID And AP_PaymentHeader.PeriodID = @PeriodID And UsersInDocumentType.UserID = @UserID and SET_DocumentType.DocumentType like '%Direct Payment%' AND AP_PaymentHeader.StatusCode = 1 and SET_DocumentType.DocumentType not like '%opening%' And IsNull(AP_PaymentHeader.IsInvoiceAdjusted, 0) = 0 {0}
Union
select Distinct AP_PaymentHeader.PaymentID, AP_PaymentHeader.DocumentNo, SET_DocumentType.DocumentType, AP_PaymentHeader.DocumentDate from AP_PaymentHeader Inner Join Set_DocumentType ON Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID AND SET_DocumentType.CompanyID = AP_PaymentHeader.CompanyID AND SET_DocumentType.PeriodID = AP_PaymentHeader.PeriodID AND Set_DocumentType.Status = 1 Inner Join UsersInDocumentType On UsersInDocumentType.CompanyID = Set_DocumentType.CompanyID And UsersInDocumentType.DocumentTypeID = Set_DocumentType.DocumentTypeID where AP_PaymentHeader.Status = 1 And AP_PaymentHeader.CompanyID = @CompanyID And AP_PaymentHeader.PeriodID = @PeriodID And UsersInDocumentType.UserID = @UserID and SET_DocumentType.DocumentType like 'Advance Against PO%' AND AP_PaymentHeader.StatusCode = 1 and SET_DocumentType.DocumentType not like '%opening%' And IsNull(AP_PaymentHeader.IsInvoiceAdjusted, 0) = 0 {0}
) As FinTab
Order By FinTab.DocumentNo, FinTab.DocumentDate, FinTab.DocumentType

select DISTINCT 'For' + ' ' + (SET_Business.BusinessName + ' ' + SET_OperatingUnit.OperatingUnitName) AS CompanyName ,AR_SET_Customer .CustomerName AS CustomerName ,AP_PaymentBanksDetail.Amount as NetPayableAmount from AP_PaymentHeader INNER JOIN SET_Company ON SET_Company.CompanyId = AP_PaymentHeader.CompanyID INNER JOIN SET_Business ON SET_Business.BusinessId = SET_Company.BusinessId INNER JOIN SET_OperatingUnit ON SET_OperatingUnit.OperatingUnitId = SET_Company.OperatingUnitId inner join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID
inner join AP_PaymentBanksDetail on AP_PaymentBanksDetail .PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail .CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail .PeriodID = AP_PaymentHeader.PeriodID inner join AR_SET_Customer on AR_SET_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID {0}
union all
select DISTINCT 'For' + ' ' + (SET_Business.BusinessName + ' ' + SET_OperatingUnit.OperatingUnitName) AS CompanyName ,AR_SET_Customer .CustomerName AS CustomerName ,AP_PaymentBanksDetail.Amount as NetPayableAmount from AP_PaymentHeader INNER JOIN SET_Company ON SET_Company.CompanyId = AP_PaymentHeader.CompanyID INNER JOIN SET_Business ON SET_Business.BusinessId = SET_Company.BusinessId INNER JOIN SET_OperatingUnit ON SET_OperatingUnit.OperatingUnitId = SET_Company.OperatingUnitId inner join AR_SET_Customer on AR_SET_Customer.CustomerID = AP_PaymentHeader.VendorID inner join AP_PaymentBanksDetail on AP_PaymentBanksDetail .PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail .CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail .PeriodID = AP_PaymentHeader.PeriodID {0}

Select *,ROW_NUMBER() Over (Order by paymentid desc) as 'Row' from ( SELECT distinct AP_PaymentHeader.CompanyID, AP_PaymentHeader.PeriodID, AP_PaymentHeader.PaymentID, AP_PaymentHeader.DocumentTypeID, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.AddressVerificationCode, AP_PaymentHeader.Amount,AP_PaymentHeader.ControlCredit, AP_PaymentHeader.AntiCipatedClearingDate, AP_PaymentHeader.PayFromCustomerID, AP_PaymentHeader.PaymentServerOrderNo, AP_PaymentHeader.PostMarkDate, AP_PaymentHeader.ProgramID, AP_PaymentHeader.ReceiptDate, AP_PaymentHeader.ReceiptMethodID, AP_PaymentHeader.ReceiptNo, AP_PaymentHeader.Comments, AP_PaymentHeader.CurrencyId, AP_PaymentHeader.BankAccountID, AP_PaymentHeader.CustomerBankBranchID, AP_PaymentHeader.CustomerReceiptReference, AP_PaymentHeader.DepositDate, AP_PaymentHeader.ExchangeDate, AP_PaymentHeader.ExchangeRate, AP_PaymentHeader.ExchangeRateType, AP_PaymentHeader.FactorDiscountAmount, AP_PaymentHeader.IssueDate, AP_PaymentHeader.IssuerBankBranchID, AP_PaymentHeader.IssuerName, AP_PaymentHeader.OverRemitAccountFlag, AP_PaymentHeader.ReceivablesTrxID, AP_PaymentHeader.Reference, AP_PaymentHeader.ReferenceType, AP_PaymentHeader.RemittanceBankAccount, AP_PaymentHeader.ReversalCategory, AP_PaymentHeader.ReversalComments, AP_PaymentHeader.ReversalDate, AP_PaymentHeader.ReversalReasonCode, AP_PaymentHeader.SelectedForFactoringFlag, AP_PaymentHeader.SelectedRemittanceBatchID, AP_PaymentHeader.ApprovalCode, AP_PaymentHeader.StatusCode, AP_PaymentHeader.OverrideRemitAccountFlag, AP_PaymentHeader.ConfirmedFlag, AP_PaymentHeader.Status, AP_PaymentHeader.CreatedBy, AP_PaymentHeader.CreateDate, AP_PaymentHeader.UpdatedBy, AP_PaymentHeader.UpdateDate, AP_PaymentHeader.CreatedByValue, AP_PaymentHeader.UpdatedByValue, AR_SET_Customer.CustomerID, -- AR_SET_Customer.CustomerName, isnull(AR_SET_Customer.CustomerName,ISNULL( ( SELECT STUFF( ( SELECT distinct ', ' + AR_SET_Customer.CustomerName FROM AP_PaymentSupplierDetail inner join AR_SET_Customer on AR_SET_Customer.CustomerID = AP_PaymentSupplierDetail.SupplierID WHERE payment1.PaymentID = AP_PaymentSupplierDetail.PaymentHeaderID and payment1.CompanyID = AP_PaymentSupplierDetail.CompanyID and AP_PaymentSupplierDetail.Status = 1 --ORDER BY AP_PaymentSupplierDetail.SupplierID FOR XML PATH(''), TYPE ).value('.', 'varchar(max)'), 1, 2, '') AS CustomerName FROM AP_PaymentHeader payment1 where payment1.PaymentID = AP_PaymentHeader.PaymentID and payment1.CompanyID = AP_PaymentHeader.CompanyID and payment1.PeriodID = AP_PaymentHeader.PeriodID ), '')) as CustomerName, SET_DocumentType.DocumentType, Set_PeriodCustom.PeriodSetName --ROW_NUMBER() Over (Order by AP_PaymentHeader.paymentid desc) as 'Row' FROM AP_PaymentHeader INNER JOIN SET_DocumentType ON AP_PaymentHeader.CompanyID = SET_DocumentType.CompanyID AND AP_PaymentHeader.Status = 1 and AP_PaymentHeader.PeriodID = SET_DocumentType.PeriodID AND AP_PaymentHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID AND SET_DocumentType.DocumentTypeID IN (4,5,143,68,69) -- Including only Payment Against Direct Invoices Inner Join UsersInDocumentType ON UsersInDocumentType.Documenttypeid = SET_DocumentType.DocumentTypeID AND UsersInDocumentType.CompanyID = SET_DocumentType.CompanyID AND UsersInDocumentType.UserID = @UserID left outer JOIN AR_SET_Customer ON AP_PaymentHeader.PeriodID = AR_SET_Customer.PeriodID --AP_PaymentHeader.CompanyID = AR_SET_Customer.CompanyID AND AP_PaymentHeader.VendorID = AR_SET_Customer.CustomerID AND AR_SET_Customer.Status = 1 inner join Set_PeriodCustom on AP_PaymentHeader.DocumentDate between Set_PeriodCustom.StartDate and Set_PeriodCustom.EndDate and Set_PeriodCustom.Status=1 and SET_PeriodCustom.FiscalID = @CurrentFiscalID left join AP_PaymentSupplierDetail on AP_PaymentSupplierDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentSupplierDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentSupplierDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentSupplierDetail.InvoiceNumber is not null
left join AP_PaymentInvoicesDetail on AP_PaymentHeader.PaymentID = AP_PaymentInvoicesDetail.PaymentHeaderID and AP_PaymentHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID and AP_PaymentHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID and AP_PaymentInvoicesDetail.status = 1 left JOIN AR_InvoiceHeader ON AR_InvoiceHeader.CompanyID = AP_PaymentInvoicesDetail.CompanyID AND AR_InvoiceHeader.PeriodID = AP_PaymentInvoicesDetail.PeriodID AND AR_InvoiceHeader.InvoiceID = AP_PaymentInvoicesDetail.InvoiceHeaderID AND AR_InvoiceHeader.Status = 1
LEFT JOIN AP_PaymentBanksDetail on AP_PaymentBanksDetail.PaymentHeaderID = [AP_PaymentHeader].PaymentID AND AP_PaymentBanksDetail.CompanyID = [AP_PaymentHeader].CompanyID AND AP_PaymentBanksDetail.PeriodID = [AP_PaymentHeader].PeriodID AND AP_PaymentBanksDetail.FiscalID = [AP_PaymentHeader].FiscalID AND AP_PaymentBanksDetail.Status = 1
inner join AR_SET_BankBranch on AR_SET_BankBranch.BankBranchID = AP_PaymentBanksDetail.BankBranchID inner join AR_SET_BankAccount on AR_SET_BankAccount.BankAccountID = AP_PaymentBanksDetail.BankAccountID
{0}
) as tab
